CREATE SCHEMA sounds;
CREATE TABLE sounds.species (species text PRIMARY KEY, group_name text NOT NULL, common_name text, usnm_specimens integer, usnm_with_coordinates integer);
CREATE TABLE sounds.licenses (license text PRIMARY KEY, allows_commercial_use boolean NOT NULL, allows_derivatives boolean NOT NULL, requires_share_alike boolean NOT NULL);
CREATE TABLE sounds.recordings (recording_id text PRIMARY KEY, group_name text NOT NULL, species text NOT NULL REFERENCES sounds.species(species), call_type text NOT NULL,
  country text, latitude double precision, longitude double precision, recorded_on date, recorded_year integer, recordist text,
  license text NOT NULL REFERENCES sounds.licenses(license), source text, source_ref text, audio_url text, image_url text);
COMMENT ON TABLE sounds.species IS 'One row per species that has at least one recording, with the number of Smithsonian NMNH (USNM) specimens held for it.';
COMMENT ON TABLE sounds.recordings IS 'One row per audio recording (a bird song or call, a fish sound), with who recorded it, where and when, the licence, and links to the audio file and its spectrogram image.';
COMMENT ON TABLE sounds.licenses IS 'One row per licence found on the recordings, with what it permits.';
COMMENT ON COLUMN sounds.species.species IS 'Scientific name (genus species).';
COMMENT ON COLUMN sounds.species.group_name IS 'bird or fish.';
COMMENT ON COLUMN sounds.species.common_name IS 'English name, when the source gives one.';
COMMENT ON COLUMN sounds.species.usnm_specimens IS 'Number of specimen records for this species held by the Smithsonian NMNH (institution code USNM), from GBIF. Only filled for the bird species.';
COMMENT ON COLUMN sounds.species.usnm_with_coordinates IS 'How many of those specimen records have latitude and longitude. A subset of usnm_specimens.';
COMMENT ON COLUMN sounds.recordings.recording_id IS 'Recording id: xc<number> for Xeno-canto birds, fs<number> for FishSounds fish.';
COMMENT ON COLUMN sounds.recordings.group_name IS 'bird or fish.';
COMMENT ON COLUMN sounds.recordings.species IS 'Scientific name; joins to species.species.';
COMMENT ON COLUMN sounds.recordings.call_type IS 'What the animal is doing: for birds song, call, alarm call, imitation, uncertain and similar; for fish grunt, drum, growl, knock, chorus, cough, snitch, moan, call, read from the file name. ''unspecified'' when the source names no particular sound.';
COMMENT ON COLUMN sounds.recordings.country IS 'Where it was recorded. Empty for fish: the fish sources give no country.';
COMMENT ON COLUMN sounds.recordings.latitude IS 'Decimal degrees; empty for fish.';
COMMENT ON COLUMN sounds.recordings.longitude IS 'Decimal degrees; empty for fish.';
COMMENT ON COLUMN sounds.recordings.recorded_on IS 'Date of the recording. Only birds have a full date; fish have only recorded_year.';
COMMENT ON COLUMN sounds.recordings.recorded_year IS 'Year of the recording (birds: the year of recorded_on; fish: the publication year in the source file name).';
COMMENT ON COLUMN sounds.recordings.recordist IS 'Person who made the recording (birds) or the first author of the study (fish).';
COMMENT ON COLUMN sounds.recordings.license IS 'Licence text, joins to licenses.license.';
COMMENT ON COLUMN sounds.recordings.source IS 'Where the recording comes from.';
COMMENT ON COLUMN sounds.recordings.source_ref IS 'Link to the source record (GBIF occurrence for birds, the data repository for fish).';
COMMENT ON COLUMN sounds.recordings.audio_url IS 'Link to the audio file.';
COMMENT ON COLUMN sounds.recordings.image_url IS 'Link to the spectrogram image of the recording.';
COMMENT ON COLUMN sounds.licenses.license IS 'Licence name, for example CC BY-NC 4.0.';
COMMENT ON COLUMN sounds.licenses.allows_commercial_use IS 'true when the licence allows commercial use. All licences on these recordings are non-commercial, so it is false for every row.';
COMMENT ON COLUMN sounds.licenses.allows_derivatives IS 'false when the licence forbids derived works (ND), true otherwise.';
COMMENT ON COLUMN sounds.licenses.requires_share_alike IS 'true when derived works must carry the same licence (SA).';
-- the app reads as a SELECT-only account
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='omnigate_ro') THEN CREATE ROLE omnigate_ro LOGIN PASSWORD 'omnigate_ro'; END IF; END $$;
GRANT USAGE ON SCHEMA sounds TO omnigate_ro; GRANT SELECT ON ALL TABLES IN SCHEMA sounds TO omnigate_ro;
